import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  SyncGroup Request (Version: 3) => group_id generation_id member_id group_instance_id [assignments]
    group_id => STRING
    generation_id => INT32
    member_id => STRING
    group_instance_id => NULLABLE_STRING
    assignments => member_id assignment
      member_id => STRING
      assignment => BYTES
*/
export function createRequest(groupId, generationId, memberId, groupInstanceId, _protocolType, _protocolName, assignments) {
    return Writer.create()
        .appendString(groupId, false)
        .appendInt32(generationId)
        .appendString(memberId, false)
        .appendString(groupInstanceId, false)
        .appendArray(assignments, (w, a) => w.appendString(a.memberId, false).appendBytes(a.assignment, false), false, false);
}
/*
  SyncGroup Response (Version: 3) => throttle_time_ms error_code assignment
    throttle_time_ms => INT32
    error_code => INT16
    assignment => BYTES
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const response = {
        throttleTimeMs: reader.readInt32(),
        errorCode: reader.readInt16(),
        protocolType: null,
        protocolName: null,
        assignment: reader.readBytes(false)
    };
    if (response.errorCode !== 0) {
        throw new ResponseError(apiKey, apiVersion, { '/': [response.errorCode, null] }, response);
    }
    return response;
}
export const api = createAPI(14, 3, createRequest, parseResponse, false, false);
